import { formatUnits } from 'viem'

const PCTS = [10, 25, 50, 75, 100]

export default function PctBtns({ balance, decimals = 18, isNative, amount, setAmount }) {
  function apply(pct) {
    let val = BigInt(balance) * BigInt(pct) / 100n
    // leave gas buffer for native tokens at 100%
    if (isNative && pct === 100) val = val - BigInt(2e15) > 0n ? val - BigInt(2e15) : val
    const formatted = formatUnits(val, decimals)
    // trim trailing zeros
    setAmount(parseFloat(formatted).toString())
  }
  return (
    <div className="pct-btns">
      {PCTS.map(p => (
        <button key={p} className="pct-btn" onClick={() => apply(p)}>{p}%</button>
      ))}
    </div>
  )
}
